
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';


gsap.registerPlugin(ScrollTrigger);


export function initCharacterReveal(element) {
    const originalText = element.textContent.trim();


    element.textContent = '';
    element.style.position = 'relative';


    const words = originalText.split(/\s+/).filter(word => word.length > 0);

    words.forEach((word, wordIndex) => {
        const wordSpan = document.createElement('span');
        wordSpan.className = 'word';
        wordSpan.style.display = 'inline-block';
        wordSpan.style.whiteSpace = 'nowrap';

        // Split word into characters
        const chars = word.split('');
        chars.forEach(char => {
            const charSpan = document.createElement('span');
            charSpan.textContent = char;
            charSpan.className = 'char';
            charSpan.style.display = 'inline-block';
            charSpan.style.opacity = '0';
            wordSpan.appendChild(charSpan);
        });

        element.appendChild(wordSpan);


        if (wordIndex < words.length - 1) {
            element.appendChild(document.createTextNode(' '));
        }
    });

    const allChars = element.querySelectorAll('.char');


    gsap.fromTo(allChars,
        { y: 15, opacity: 0 },
        {
            opacity: 1,
            y: 0,
            stagger: 0.03,
            duration: 0.8,
            ease: "power2.out",
            scrollTrigger: {
                trigger: element,
                start: 'top 85%',
                once: true
            }
        }
    );
}


export function initTypingAnimations() {
    const typingElements = document.querySelectorAll('.typing-text');
    typingElements.forEach(element => {
        initCharacterReveal(element);
    });
}
